// msg.topic = "nodoA/estado" o "nodoB/estado"
// Se guarda el ultimo estado de cada nodo con la hora de llegada
const nodo = msg.payload && msg.payload.nodo;
if (nodo !== 'A' && nodo !== 'B') return null;
const estados = flow.get('estados') || {};
estados[nodo] = { datos: msg.payload, t: Date.now() };
flow.set('estados', estados);
return msg;

// msg.topic = "nodoA/conexion"; payload = "online" u "offline"
// "offline" lo publica el broker (Last Will) cuando un nodo desaparece
const nodo = msg.topic.startsWith('nodoA') ? 'A' : (msg.topic.startsWith('nodoB') ? 'B' : null);
if (!nodo) return null;
const conexion = flow.get('conexion') || {};
conexion[nodo] = { valor: String(msg.payload).trim(), t: Date.now() };
flow.set('conexion', conexion);
return msg;

// Busca el comando por su id y anota la respuesta del nodo que confirma
const a = msg.payload || {};
if (!a.id || (a.nodo !== 'A' && a.nodo !== 'B')) return null;
const historial = flow.get('historial') || [];
const cmd = historial.find(c => c.id === a.id);
if (!cmd) return null;   // ack de un comando que no envio esta plataforma
cmd.resp[a.nodo] = { ok: a.ok === true, error: a.error || '', t: Date.now() };
flow.set('historial', historial);
return msg;

// El nodo status reporta el estado de la conexion del nodo MQTT.
// Verde = conectado. Se usa el color y no el texto porque el texto
// es una clave de traduccion ("node-red:common.status.connected").
const conectado = msg.status && msg.status.fill === 'green';
flow.set('broker', { conectado: conectado, t: Date.now() });
return msg;

// Arma el contenido de todas las tarjetas a partir del contexto del flujo.
// Salidas: 1 Nodo A | 2 Nodo B | 3 Sistema | 4 Historial | 5 Temp A | 6 Hum B | 7 Extractor B
const ahora = Date.now();
const estados   = flow.get('estados')   || {};
const conexion  = flow.get('conexion')  || {};
const broker    = flow.get('broker')    || { conectado: false };
const historial = flow.get('historial') || [];
const TIMEOUT_ACK_MS = 5000;

function hace(t) {
  const s = Math.round((ahora - t) / 1000);
  if (s < 60) return s + ' s';
  return Math.floor(s / 60) + ' min ' + (s % 60) + ' s';
}
function uptime(s) {
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
  return (h ? h + ' h ' : '') + m + ' min';
}

// Estado de conexion de un nodo, de mas grave a menos grave
function estadoConexion(nodo) {
  const e = estados[nodo];
  const c = conexion[nodo];
  if (!broker.conectado) return { texto: 'Sin conexión con el broker', clase: 'mal', vigente: false };
  if (c && c.valor === 'offline' && (!e || c.t >= e.t))
    return { texto: 'Desconectado (Last Will)', clase: 'mal', vigente: false };
  if (!e) return { texto: 'Sin datos', clase: 'gris', vigente: false };
  // Se espera un estado por intervalo: 3 intervalos sin datos = datos viejos
  const limite = Math.max(15000, 3 * (e.datos.intervaloMs || 5000));
  if (ahora - e.t > limite)
    return { texto: 'Sin datos recientes · último hace ' + hace(e.t), clase: 'alerta', vigente: false };
  return { texto: 'En línea · actualizado hace ' + hace(e.t), clase: 'bien', vigente: true };
}

function fila(etiqueta, valor, clase) { return { etiqueta, valor, clase: clase || '' }; }

const TEXTO_LED = { off: 'Apagado (normal)', lento: 'Parpadeo lento (falla)', rapido: 'Parpadeo rápido (alarma)', on: 'Encendido fijo (manual)' };
const TEXTO_REINICIO = { encendido: 'Encendido o botón EN', software: 'Reinicio por software', falla: 'Falla del programa', watchdog: 'Watchdog: loop trabado', watchdog_int: 'Watchdog de interrupción', watchdog_otro: 'Watchdog', brownout: 'Caída de voltaje', externo: 'Reset externo' };
function filaReinicio(r) {
  if (!r) return fila('Último reinicio', 'Sin dato (firmware anterior)', 'gris');
  return fila('Último reinicio', TEXTO_REINICIO[r] || r, r === 'encendido' ? '' : 'mal');
}
const TEXTO_MOTIVO = { humedad: 'humedad alta en B', temperaturaA: 'temperatura alta en A', preventivo: 'preventivo: falta información confiable', normal: 'todo normal', manual: 'control manual' };

function vistaA() {
  const con = estadoConexion('A');
  const e = estados.A;
  if (!e) return { titulo: 'Nodo A', conexion: con.texto, claseConexion: con.clase, filas: [] };
  const d = e.datos;
  const f = [];
  f.push(d.sensorOk ? fila('Temperatura', d.temp + ' °C') : fila('Temperatura', 'Sensor en falla', 'mal'));
  f.push(d.alarmaTemp ? fila('Alarma de temperatura', 'ACTIVA', 'mal') : fila('Alarma de temperatura', 'Normal', 'bien'));
  f.push(fila('LED', TEXTO_LED[d.led] || d.led, d.led === 'rapido' ? 'mal' : (d.led === 'lento' ? 'alerta' : '')));
  f.push(fila('Modo', d.modo === 'auto' ? 'Automático' : 'Manual', d.modo === 'manual' ? 'alerta' : ''));
  f.push(fila('Umbral', 'Activa en ' + d.umbralTemp + ' °C · se apaga en ' + (d.umbralTemp - d.histeresis) + ' °C'));
  f.push(fila('Muestreo', 'Cada ' + (d.intervaloMs / 1000) + ' s'));
  f.push(d.enlaceB ? fila('Enlace ESP-NOW con B', 'Activo', 'bien') : fila('Enlace ESP-NOW con B', 'Caído', 'mal'));
  f.push(fila('Alarma de humedad recibida de B', d.alarmaHumB ? 'Sí' : 'No', d.alarmaHumB ? 'mal' : ''));
  f.push(fila('Mensajes perdidos de B', String(d.perdidosB)));
  f.push(fila('Señal WiFi', d.rssi + ' dBm'));
  f.push(fila('Encendido hace', uptime(d.uptimeS)));
  f.push(filaReinicio(d.reinicio));
  if (!con.vigente) f.forEach(x => x.clase = 'gris');
  return { titulo: 'Nodo A', conexion: con.texto, claseConexion: con.clase, filas: f };
}

function vistaB() {
  const con = estadoConexion('B');
  const e = estados.B;
  if (!e) return { titulo: 'Nodo B', conexion: con.texto, claseConexion: con.clase, filas: [] };
  const d = e.datos;
  const f = [];
  f.push(d.sensorOk ? fila('Humedad relativa', d.hum + ' %') : fila('Humedad relativa', 'Sensor en falla', 'mal'));
  f.push(d.alarmaHum ? fila('Alarma de humedad', 'ACTIVA', 'mal') : fila('Alarma de humedad', 'Normal', 'bien'));
  f.push(fila('Extractor', d.extractor + ' % · ' + (TEXTO_MOTIVO[d.motivo] || d.motivo), d.motivo === 'humedad' || d.motivo === 'temperaturaA' ? 'mal' : (d.motivo === 'preventivo' ? 'alerta' : '')));
  f.push(fila('Modo', d.modo === 'auto' ? 'Automático' : 'Manual', d.modo === 'manual' ? 'alerta' : ''));
  f.push(fila('Umbral', 'Activa en ' + d.umbralHum + ' % · se apaga en ' + (d.umbralHum - d.histeresisHum) + ' %'));
  f.push(fila('Muestreo', 'Cada ' + (d.intervaloMs / 1000) + ' s'));
  f.push(d.enlaceA ? fila('Enlace ESP-NOW con A', 'Activo', 'bien') : fila('Enlace ESP-NOW con A', 'Caído', 'mal'));
  f.push(fila('Alarma de temperatura recibida de A', d.alarmaTempA ? 'Sí' : 'No', d.alarmaTempA ? 'mal' : ''));
  f.push(fila('Mensajes perdidos de A', String(d.perdidosA)));
  f.push(fila('Señal WiFi', d.rssi + ' dBm'));
  f.push(fila('Encendido hace', uptime(d.uptimeS)));
  f.push(filaReinicio(d.reinicio));
  if (!con.vigente) f.forEach(x => x.clase = 'gris');
  return { titulo: 'Nodo B', conexion: con.texto, claseConexion: con.clase, filas: f };
}

function vistaSistema() {
  const ca = estadoConexion('A'), cb = estadoConexion('B');
  return {
    titulo: 'Sistema',
    conexion: broker.conectado ? 'Broker MQTT conectado' : 'Broker MQTT desconectado',
    claseConexion: broker.conectado ? 'bien' : 'mal',
    filas: [
      fila('Nodo A', ca.texto, ca.clase),
      fila('Nodo B', cb.texto, cb.clase)
    ]
  };
}

// Estado de cada comando: confirmado, rechazado, pendiente o sin respuesta
function vistaHistorial() {
  return historial.map(c => {
    const partes = c.esperados.map(n => {
      const r = c.resp[n];
      if (r) return r.ok ? { texto: n + ': confirmado', clase: 'bien' }
                         : { texto: n + ': rechazado · ' + r.error, clase: 'mal' };
      if (ahora - c.t > TIMEOUT_ACK_MS) return { texto: n + ': sin respuesta', clase: 'alerta' };
      return { texto: n + ': pendiente', clase: 'gris' };
    });
    const hora = new Date(c.t).toLocaleTimeString('es-GT', { hour12: false });
    return { id: c.id, hora, destino: c.destino, texto: c.texto, partes };
  });
}

// Medidores: solo con datos vigentes y sensor funcionando
const salidaTemp = (estadoConexion('A').vigente && estados.A.datos.sensorOk) ? { payload: estados.A.datos.temp } : null;
const salidaHum  = (estadoConexion('B').vigente && estados.B.datos.sensorOk) ? { payload: estados.B.datos.hum } : null;
const salidaExt  = estadoConexion('B').vigente ? { payload: estados.B.datos.extractor } : null;

return [
  { payload: vistaA() },
  { payload: vistaB() },
  { payload: vistaSistema() },
  { payload: vistaHistorial() },
  salidaTemp, salidaHum, salidaExt
];

// El formulario entrega todos sus campos. Solo se envian los que el
// usuario lleno: un campo vacio no debe cambiar esa variable en el nodo.
// La validacion de rangos la hace el nodo (es la fuente de verdad).
const NODO = 'A';
const cmd = { destino: NODO, accion: 'set' };
let hay = false;
for (const [k, v] of Object.entries(msg.payload || {})) {
  if (v === '' || v === null || v === undefined) continue;
  const n = Number(v);
  if (Number.isNaN(n)) continue;
  cmd[k] = n;
  hay = true;
}
if (!hay) { node.warn('Formulario sin valores: no se envia nada'); return null; }
msg.payload = cmd;
return msg;

// El formulario entrega todos sus campos. Solo se envian los que el
// usuario lleno: un campo vacio no debe cambiar esa variable en el nodo.
// La validacion de rangos la hace el nodo (es la fuente de verdad).
const NODO = 'B';
const cmd = { destino: NODO, accion: 'set' };
let hay = false;
for (const [k, v] of Object.entries(msg.payload || {})) {
  if (v === '' || v === null || v === undefined) continue;
  const n = Number(v);
  if (Number.isNaN(n)) continue;
  cmd[k] = n;
  hay = true;
}
if (!hay) { node.warn('Formulario sin valores: no se envia nada'); return null; }
msg.payload = cmd;
return msg;

// Recibe { destino: 'A' | 'B' | 'todos', accion, ...parametros }
// 1. Genera un id unico (el nodo ignora un id repetido)
// 2. Lo registra en el historial con los nodos que deben confirmar
// 3. Lo publica en el topico del destino con QoS 1
const c = msg.payload || {};
const destinos = { A: 'nodoA/cmd', B: 'nodoB/cmd', todos: 'todos/cmd' };
if (!destinos[c.destino] || !c.accion) { node.warn('Comando sin destino o accion'); return null; }

// id = "p" + milisegundos en base 36 + contador: unico aunque se pulsen
// dos botones en el mismo milisegundo, y de menos de 31 caracteres
let n = context.get('contador') || 0;
context.set('contador', (n + 1) % 1000);
const id = 'p' + Date.now().toString(36) + n;

const cuerpo = { id: id, accion: c.accion };
for (const [k, v] of Object.entries(c)) if (k !== 'destino' && k !== 'accion') cuerpo[k] = v;

// Texto legible para el historial: "set umbralTemp=25" o "led on"
const params = Object.entries(cuerpo).filter(([k]) => k !== 'id' && k !== 'accion')
  .map(([k, v]) => k === 'valor' ? String(v) : k + '=' + v).join(' ');
const historial = flow.get('historial') || [];
historial.unshift({
  id: id,
  destino: c.destino === 'todos' ? 'Ambos' : 'Nodo ' + c.destino,
  texto: (c.accion + ' ' + params).trim(),
  esperados: c.destino === 'todos' ? ['A', 'B'] : [c.destino],
  resp: {},
  t: Date.now()
});
flow.set('historial', historial.slice(0, 10));   // solo los ultimos 10

return [{ topic: destinos[c.destino], payload: JSON.stringify(cuerpo), qos: 1, retain: false }, { payload: 'nuevo' }];
